"use strict";(self.webpackChunkthe_indian_justice_academy=self.webpackChunkthe_indian_justice_academy||[]).push([["8132"],{6637(e,t,i){i.r(t),i.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>r,contentTitle:()=>s,toc:()=>h,assets:()=>d});var a=JSON.parse('{"id":"the-advocates-act-1961/legal-profession-in-india","title":"Legal Profession in India","description":"History and development of the legal profession in India \u2014 from the Mayor\'s Courts and the Supreme Court of Judicature to the High Courts, the Indian Bar Councils Act, 1926 and the Advocates Act, 1961.","source":"@site/docs/the-advocates-act-1961/legal-profession-in-india.md","sourceDirName":"the-advocates-act-1961","slug":"/the-advocates-act-1961/legal-profession-in-india","permalink":"/theindianjustice-academy/docs/the-advocates-act-1961/legal-profession-in-india","draft":false,"unlisted":false,"editUrl":"#/docs/the-advocates-act-1961/legal-profession-in-india.md","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"id":"legal-profession-in-india","title":"Legal Profession in India","sidebar_label":"Legal Profession in India","sidebar_position":2,"description":"History and development of the legal profession in India \u2014 from the Mayor\'s Courts and the Supreme Court of Judicature to the High Courts, the Indian Bar Councils Act, 1926 and the Advocates Act, 1961.","keywords":["legal profession in India","professional ethics","Advocates Act 1961","Indian Bar Councils Act 1926","Mayor\'s Court","High Courts"]},"sidebar":"tutorialSidebar","previous":{"title":"K. V. Krishnaswami Aiyar\'s Professional Conduct and Advocacy","permalink":"/theindianjustice-academy/docs/the-advocates-act-1961/K-V-Krishnaswami-Aiyar"},"next":{"title":"Blog on Senior Advocate","permalink":"/theindianjustice-academy/docs/the-advocates-act-1961/senior-advocate"}}'),n=i(4848),o=i(8453);let r={id:"legal-profession-in-india",title:"Legal Profession in India",sidebar_label:"Legal Profession in India",sidebar_position:2,description:"History and development of the legal profession in India \u2014 from the Mayor's Courts and the Supreme Court of Judicature to the High Courts, the Indian Bar Councils Act, 1926 and the Advocates Act, 1961.",keywords:["legal profession in India","professional ethics","Advocates Act 1961","Indian Bar Councils Act 1926","Mayor's Court","High Courts"]},s="Legal Profession in India",d={},h=[{value:"Establishment of the High Courts",id:"establishment-of-the-high-courts",level:2},{value:"Original and appellate jurisdiction of the High Court",id:"original-and-appellate-jurisdiction-of-the-high-court",level:2},{value:"Indian Bar Councils Act, 1926",id:"indian-bar-councils-act-1926",level:2}];function l(e){let t={blockquote:"blockquote",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",ul:"ul",...(0,o.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"legal-profession-in-india",children:"Legal Profession in India"})}),"\n",(0,n.jsx)(t.p,{children:"The history of the legal profession in India can be traced back to the establishment of the First British Court in Bombay in 1672 by Governor Aungier. The admission of attorneys was placed in the hands of the Governor-in-Council and not with the Court. Prior to the establishment of the Mayor's Courts in 1726 in Madras and Calcutta, there were no legal practitioners."}),"\n",(0,n.jsx)(t.p,{children:"The Mayor's Courts, established in the three presidency towns, were Crown Courts with right of appeal first to the Governor-in-Council and a right of second appeal to the Privy Council. In 1791, Judges felt the need of experience, and thus the role of an attorney to protect the rights of his client was upheld in each of the Mayor's Courts. This was done in spite of opposition from Council members or the Governor. A second principle was also established during the period of the Mayor's Courts. This was the right to dismiss an attorney guilty of misconduct. The first example of dismissal was recorded by the Mayor's Court at Madras which dismissed attorney Jones."}),"\n",(0,n.jsx)(t.p,{children:"The Supreme Court of Judicature was established by a Royal Charter in 1774. The Supreme Court was established as there was dissatisfaction with the weaknesses of the Court of the Mayor. Similar Supreme Courts were established in Madras in 1801 and Bombay in 1823. The first barristers appeared in India after the opening of the Supreme Court in Calcutta in 1774. As barristers began to come into the Courts on work as advocates, the attorneys gave up pleading and worked as solicitors. The two grades of legal practice gradually became distinct and separate as they were in England. Madras gained its first barrister in 1778 with Mr. Benjamin Sullivan."}),"\n",(0,n.jsx)(t.p,{children:"Thus, the establishment of the Supreme Court brought recognition, wealth and prestige to the legal profession. The charters of the Court stipulated that the Chief Justice and three puisne Judges be English barristers of at least 5 years standing."}),"\n",(0,n.jsx)(t.p,{children:"The charters empowered the Court to approve, admit and enrol advocates and attorneys to plead and act on behalf of suitors. They also gave the Court the authority to remove lawyers from the roll of the Court on reasonable cause and to prohibit practitioners not properly admitted and enrolled from practising in the Court. The Court maintained the right to admit, discipline and dismiss attorneys and barristers. Attorneys were not admitted without recommendation from a high official in England or a Judge in India. Permission to practice in Court could be refused even to a barrister."}),"\n",(0,n.jsx)(t.p,{children:"In contrast to the Courts in the presidency towns, the legal profession in the mofussil towns was established, guided and controlled by legislation. In the Diwani Courts, legal practice was neither recognized nor controlled, and practice was carried on by vakils and agents. Vakils had even been appearing in the Courts of the Nawabs and there were no laws concerning their qualification, relationship to the Court, mode of procedure of ethics or practice. There were two kinds of agents:"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsx)(t.li,{children:"untrained relatives or servants of the parties in Court, and"}),"\n",(0,n.jsx)(t.li,{children:"professional pleaders who had training in either Hindu or Muslim law."}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"Bengal Regulation VII of 1793 was enacted as it was felt that in order to administer justice, Courts must have pleading of causes administered by a distinct profession. Only men of character and education, well versed in the Mohamedan or Hindu law and in the Regulations passed by the British Government, would be admitted to plead in the Courts. They should be subjected to rules and restrictions in order to discharge their work diligently and faithfully by upholding the client's trust."}),"\n",(0,n.jsx)(t.h2,{id:"establishment-of-the-high-courts",children:"Establishment of the High Courts"}),"\n",(0,n.jsx)(t.p,{children:"In 1862, the High Courts started by the Crown were established at Calcutta, Bombay and Madras. The High Court Bench was designed to combine Supreme Court and Sudder Court traditions. This was done to unite the legal learning and judicial experience of the English barristers with the intimate experience of civil servants in matters of Indian customs, usages and laws possessed by the civil servants. Each of the High Courts was given the power to make rules for the qualifications of proper persons, advocates, vakils and attorneys at Bar. The admission of vakils to practice before the High Courts ended the monopoly that the barristers had enjoyed in the Supreme Courts. It greatly extended the practice and prestige of the Indian laws by giving them opportunities and privileges equal to those enjoyed for many years by the English lawyers. The learning of the best British traditions of Indian vakils began in a guru-shishya tradition:"}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:'"Men like Sir V. Bashyam Ayyangar, Sir T. Muthuswamy Ayyar and Sir S. Subramania Ayyar were quick to learn and absorb the traditions of the English Bar from their English friends and colleagues in the Madras Bar and they in turn as the originators of a long line of disciples in the Bar passed on those traditions to the disciples who continued to do the good work."'}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"Additional High Courts were established in Allahabad (1886), Patna (1916), and Lahore (1919)."}),"\n",(0,n.jsx)(t.p,{children:"There were six grades of legal practice in India after the founding of the High Courts:"}),"\n",(0,n.jsxs)(t.ol,{children:["\n",(0,n.jsx)(t.li,{children:"Advocates"}),"\n",(0,n.jsx)(t.li,{children:"Attorneys (Solicitors)"}),"\n",(0,n.jsx)(t.li,{children:"Vakils of High Courts"}),"\n",(0,n.jsx)(t.li,{children:"Pleaders"}),"\n",(0,n.jsx)(t.li,{children:"Mukhtars"}),"\n",(0,n.jsx)(t.li,{children:"Revenue Agents"}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"The Legal Practitioners Act of 1879 in fact brought all the six grades of the profession into one system under the jurisdiction of the High Courts. The Legal Practitioners Act and the Letters Patent of the High Courts formed the chief legislative governance of legal practitioners in the subordinate Courts in the country until the Advocates Act, 1961 was enacted."}),"\n",(0,n.jsx)(t.p,{children:"In order to be a vakil, the candidate had to study at a college or university, master the use of English and pass a vakil's examination. By 1940, a vakil was required to be a graduate with an LL.B. from a university in India in addition to three other certified requirements. The certificate should be proof that:"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsx)(t.li,{children:"he had passed in the examination,"}),"\n",(0,n.jsx)(t.li,{children:"read in the chamber of a qualified lawyer, and"}),"\n",(0,n.jsx)(t.li,{children:"was of a good character."}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"In fact, Sir Sunder Lal, Jogendra Nath Chaudhary, Ram Prasad and Moti Lal Nehru were all vakils who were raised to the rank of an Advocate."}),"\n",(0,n.jsx)(t.h2,{id:"original-and-appellate-jurisdiction-of-the-high-court",children:"Original and appellate jurisdiction of the High Court"}),"\n",(0,n.jsx)(t.p,{children:"The High Courts of the three presidency towns had an original side. The original side included major civil and criminal matters which had been earlier heard by predecessor Supreme Courts. On the original side in the High Courts, the solicitor and barrister remained distinct i.e. attorney and advocate. On the appellate side every lawyer practiced as his own attorney."}),"\n",(0,n.jsx)(t.p,{children:"However, in Madras the vakils started practice since 1866. In 1874, the barristers challenged their right to do original side work. However, in 1916, this right was firmly established in favour of the vakils. Similarly, vakils in Bombay and Calcutta could be promoted as advocates and become qualified to work on the original side. By attending the appellate side and original side Courts each for one year, a vakil of 10 years service in the Court was permitted to sit for the advocates' examination."}),"\n",(0,n.jsx)(t.h2,{id:"indian-bar-councils-act-1926",children:"Indian Bar Councils Act, 1926"}),"\n",(0,n.jsx)(t.p,{children:"The Indian Bar Councils Act, 1926 was passed to unify the various grades of legal practice and to provide self-government to the Bars attached to various Courts. The Act required that each High Court must constitute a Bar Council made up of the Advocate General, four men nominated by the High Court of whom two should be Judges and ten elected from among the advocates of the Bar. The duties of the Bar Council were to decide all matters concerning legal education, qualification for enrolment, discipline and control of the profession. It was favourable to the advocates as it gave them authority previously held by the judiciary to regulate the membership and discipline of their profession."}),"\n",(0,n.jsx)(t.p,{children:"The Advocates Act, 1961 was a step to further this very initiative. As a result of the Advocates Act, admission, practice, ethics, privileges, regulations, discipline and improvement of the profession as well as law reform are now significantly in the hands of the profession itself."})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},8453(e,t,i){i.d(t,{R:()=>r,x:()=>s});var a=i(6540);let n={},o=a.createContext(n);function r(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);